diff --git a/js/src/vm/Modules.cpp b/js/src/vm/Modules.cpp
index c5fc673e9ed71..92f264e55e34a 100644
--- a/js/src/vm/Modules.cpp
+++ b/js/src/vm/Modules.cpp
@@ -121,16 +121,19 @@ static ModuleObject* GetEnclosingModule(JSScript* script) {
 // Get the module record from a |referrer| value built by
 // ReferrerValueForScript, or nullptr if the referrer is not a module.
 static ModuleObject* ReferrerModuleOrNull(Handle<Value> referrer) {
-  if (!referrer.isObject()) {
-    return nullptr;
+  if (referrer.get().isDouble()) {
+    uintptr_t encoded = reinterpret_cast<uintptr_t>(referrer.get().toPrivate());
+    if ((encoded & 1) != 0) {
+      return reinterpret_cast<ModuleObject*>(encoded & ~uintptr_t(1));
+    }
   }

-  JSObject* object = &referrer.toObject();
-  if (!object->is<ModuleObject>()) {
+  if (!referrer.isObject()) {
     return nullptr;
   }

-  return &object->as<ModuleObject>();
+  JSObject* object = &referrer.toObject();
+  return object->is<ModuleObject>() ? &object->as<ModuleObject>() : nullptr;
 }

 // Build the referrer value from |script|, and the returned JS::Value is passed
@@ -144,7 +147,7 @@ static Value ReferrerValueForScript(JSScript* script) {
   MOZ_ASSERT(script, "a dynamic import call always has a running script");

   if (ModuleObject* module = GetEnclosingModule(script)) {
-    return ObjectValue(*module);
+    return PrivateValue(reinterpret_cast<uintptr_t>(module) | 1);
   }

   return script->sourceObject()->getPrivate();

